		@JvmStatic fun faceModeOf(mesh: fv_NetworkMeshData?, state: fv_NetworkStateData?, f: Int): Byte {
			var uf: Long = f.toLong()
			if ((((mesh!!.face_gate)!!.a!![uf.toInt()]).toInt() and 0xFF) != 0) {
				return (0).toByte()
			}
			if ((mesh!!.face_culvert)!!.a!![uf.toInt()] >= 0) {
