				cell_side_press = cell_side_press || pl
			}
			if (cr >= 0) {
				pr = fv_PressurizedHeadSolver.cellPressurized(mesh, state, cr)
				cell_side_press = cell_side_press || pr
			}
			if (nd >= 0) {
				var gp: Boolean = fv_PressurizedHeadSolver.ghostPressurized(mesh, state, f)
				if (cl < 0) {
					pl = gp
				}
				if (cr < 0) {
