			}
			return (if (pl && pr) 1 else 2).toByte()
		}

		@JvmStatic fun ghostPressurized(mesh: fv_NetworkMeshData?, state: fv_NetworkStateData?, f: Int): Boolean {
			var uf: Long = f.toLong()
			var nd: Int = (mesh!!.face_node)!!.a!![uf.toInt()]
			if (nd < 0) {
