			}
			var other: Int = (if ((mesh!!.face_cl)!!.a!![uf.toInt()] >= 0) cpp.RefI.Arr((mesh!!.face_cl)!!.a, uf.toInt()) else cpp.RefI.Arr((mesh!!.face_cr)!!.a, uf.toInt()))!!.get()
			if (other < 0) {
