			}
			var g: fv_FvGeometry? = (mesh!!.geom)!!.a!![((mesh!!.cell_geom)!!.a!![other.toLong().toInt()]).toLong().toInt()] as fv_FvGeometry?
			if (((g!!.is_open).toInt() and 0xFF) != 0) {
				return false
			}
			if (((!((state!!.cell_tpa)!!.empty())) && ((((state!!.cell_tpa)!!.a!![other.toLong().toInt()]).toInt() and 0xFF) != 0)) && ((mesh!!.node_sur_depth)!!.a!![nd.toLong().toInt()] > 0.0)) {
